/// <summary>
/// PaffH 18.01.21
/// find NDXRole2DutyTable
/// </summary>
/// <param name = "_RefRecIdNDXDutyTable">RefRecId</param>
/// <param name = "_RefRecIdNDXRoleTable">RefRecId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXRole2DutyTable</returns>
static NDXRole2DutyTable find(RefRecId _RefRecIdNDXDutyTable, RefRecId _RefRecIdNDXRoleTable, boolean _forUpdate = true)
{
    NDXRole2DutyTable nDXRole2DutyTable;
    nDXRole2DutyTable.selectForUpdate(_forUpdate);
    select nDXRole2DutyTable
        where nDXRole2DutyTable.RefRecIdNDXDutyTable == _RefRecIdNDXDutyTable
        &&  nDXRole2DutyTable.RefRecIdNDXRoleTable == _RefRecIdNDXRoleTable;
    return nDXRole2DutyTable;
}

/// <summary>
/// PaffH 18.01.21
/// find or create NDXRole2DutyTable
/// </summary>
/// <param name = "_RefRecIdNDXDutyTable">RefRecId</param>
/// <param name = "_RefRecIdNDXRoleTable">RefRecId</param>
/// <param name = "_insert">boolean</param>
/// <returns>NDXRole2DutyTable</returns>
static NDXRole2DutyTable findOrCreate(RefRecId _RefRecIdNDXDutyTable, RefRecId _RefRecIdNDXRoleTable, boolean _insert = true)
{
    NDXRole2DutyTable nDXRole2DutyTable;
    nDXRole2DutyTable = NDXRole2DutyTable::find(_RefRecIdNDXDutyTable, _RefRecIdNDXRoleTable, true);
    if (!nDXRole2DutyTable)
    {
        nDXRole2DutyTable.RefRecIdNDXDutyTable = _RefRecIdNDXDutyTable;
        nDXRole2DutyTable.RefRecIdNDXRoleTable = _RefRecIdNDXRoleTable;
        if (_insert)
        {
            nDXRole2DutyTable.insert();
        }
    }
    return nDXRole2DutyTable;
}

/// <summary>
/// PaffH 20.01.21
/// delete records not updated
/// </summary>
/// <param name = "_updatedUtcDateTime">NDXUpdatedUTCDateTime</param>
/// <param name = "_logger">NDXLoggerSecurityInformationClass</param>
/// <returns>counter deleted records</returns>
static public int deleteNotUpdated(NDXUpdatedUTCDateTime _updatedUtcDateTime, NDXLoggerSecurityInformationClass _logger)
{
    NDXRole2DutyTable nDXRole2DutyTable;

    NDXArgsLoggerSecuritiyInformation argsLogger = new NDXArgsLoggerSecuritiyInformation();
    argsLogger.parmLogActivity(strFmt("@NDX:NDXDeleteRecordsInTable", tableId2PName(nDXRole2DutyTable.TableId)));
    _logger.LogLineCreate(argsLogger);

    NDXHelperTable::skipForDelete(nDXRole2DutyTable);
    delete_from nDXRole2DutyTable
        where nDXRole2DutyTable.UpdatedUTCDateTime != _updatedUtcDateTime;

    argsLogger.parmCounter(int642int(nDXRole2DutyTable.RowCount()));
    _logger.LogLineChange(argsLogger);

    return int642int(nDXRole2DutyTable.RowCount());
}
